package edu.team12.deadlocklab;
import edu.team12.deadlocklab.detection.*;import edu.team12.deadlocklab.scenario.*;import edu.team12.deadlocklab.recovery.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class MatrixDetectorTest {
 private final MatrixDetector d=new MatrixDetector();
 @Test void fixturesProduceExpectedSets(){assertTrue(d.detect(ScenarioLibrary.noDeadlock()).deadlocked().isEmpty());assertEquals(List.of("P1","P2"),d.detect(ScenarioLibrary.deadlock()).deadlocked());assertTrue(d.detect(ScenarioLibrary.multiInstance()).deadlocked().isEmpty());}
 @Test void detectorIsRepeatableAndDoesNotMutateInput(){var s=ScenarioLibrary.deadlock();var before=s.allocation();assertEquals(d.detect(s),d.detect(s));assertEquals(before,s.allocation());}
 @Test void terminationReleasesResourcesAndEliminatesDeadlock(){var s=new RecoveryService().terminate(ScenarioLibrary.deadlock(),"P1");assertEquals(List.of(1,0),s.available());assertEquals(List.of(0,0),s.allocation().get(0));assertTrue(d.detect(s).deadlocked().isEmpty());}
 @Test void graphCycleDetection(){var g=new WaitForGraphDetector();assertTrue(g.hasCycle(Map.of("P1",List.of("P2"),"P2",List.of("P1"))));assertFalse(g.hasCycle(Map.of("P1",List.of("P2"),"P2",List.of())));}
 @Test void rejectsBrokenAccounting(){var s=ScenarioLibrary.deadlock();var bad=new edu.team12.deadlocklab.domain.Scenario(s.id(),s.processes(),s.resources(),s.total(),List.of(1,0),s.allocation(),s.request(),s.preemptible(),s.terminated());assertThrows(IllegalArgumentException.class,()->d.detect(bad));}
 @Test void zeroAllocationProcessStartsFinished(){var r=d.detect(ScenarioLibrary.zeroHolder());assertEquals(List.of("P2"),r.deadlocked());assertTrue(r.trace().stream().noneMatch(x->x.process().equals("P1")));}
 @Test void rejectsInvalidPreemptionAndPreservesValidAccounting(){var service=new RecoveryService();var s=ScenarioLibrary.deadlock();assertThrows(IllegalArgumentException.class,()->service.preempt(s,"P1","R1"));var allowed=new edu.team12.deadlocklab.domain.Scenario(s.id(),s.processes(),s.resources(),s.total(),s.available(),s.allocation(),s.request(),List.of(true,false),s.terminated());var changed=service.preempt(allowed,"P1","R1");assertEquals(List.of(1,0),changed.available());assertEquals(0,changed.allocation().get(0).get(0));assertEquals(1,changed.request().get(0).get(0));assertTrue(edu.team12.deadlocklab.domain.ScenarioValidator.errors(changed).isEmpty());}
 @Test void rollbackRestoresAValidatedCheckpoint(){var service=new RecoveryService();var checkpoint=ScenarioLibrary.deadlock();var edited=service.terminate(checkpoint,"P1");assertEquals(checkpoint,service.rollback(checkpoint));assertNotEquals(checkpoint,edited);}
 @Test void rejectsDimensionsDuplicateIdsNegativeAndInconsistentTotals(){var s=ScenarioLibrary.noDeadlock();var badDimension=new edu.team12.deadlocklab.domain.Scenario(s.id(),s.processes(),s.resources(),s.total(),s.available(),List.of(List.of(1)),s.request(),s.preemptible(),s.terminated());assertFalse(edu.team12.deadlocklab.domain.ScenarioValidator.errors(badDimension).isEmpty());var duplicate=new edu.team12.deadlocklab.domain.Scenario(s.id(),List.of("P1","P1"),s.resources(),s.total(),s.available(),s.allocation(),s.request(),s.preemptible(),s.terminated());assertFalse(edu.team12.deadlocklab.domain.ScenarioValidator.errors(duplicate).isEmpty());var negative=new edu.team12.deadlocklab.domain.Scenario(s.id(),s.processes(),s.resources(),s.total(),List.of(-1,0),s.allocation(),s.request(),s.preemptible(),s.terminated());assertFalse(edu.team12.deadlocklab.domain.ScenarioValidator.errors(negative).isEmpty());}
 @Test void cycleDoesNotReplaceMultiInstanceReasoning(){var graph=Map.of("P1",List.of("P2"),"P2",List.of("P1"));assertTrue(new WaitForGraphDetector().hasCycle(graph));assertTrue(d.detect(ScenarioLibrary.multiInstance()).deadlocked().isEmpty());}
}
